await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

const results = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll("[data-testid*='ProductTile'], .product-tile, div.product"));
  if (items.length === 0) {
    // fallback generic search card selectors
    const links = Array.from(document.querySelectorAll("a[href*='.product.']"));
    return links.map(a => {
      const card = a.closest(".col-xs-12, .col-sm-6, .col-lg-4, div[data-testid]") || a.parentElement;
      return {
        title: a.innerText.trim(),
        href: a.href,
        price: card?.innerText
      };
    });
  }
  return items.map(el => ({
    text: el.innerText
  }));
});

console.log({ count: results.length, sample: results.slice(0, 5) });

