const tabId = 480038377;
const results = await browserjs(tabId, () => {
  // Check for product grid or text matching "pokemon"
  const bodyText = document.body.innerText;
  const matchIndex = bodyText.toLowerCase().indexOf("pokemon");

  // Find all links on page
  const allLinks = Array.from(document.querySelectorAll("a")).map(a => ({
    text: a.innerText.trim(),
    href: a.href
  })).filter(l => l.text.length > 0 && l.text.length < 150);

  return {
    matchIndex,
    snippetAroundMatch: matchIndex !== -1 ? bodyText.substring(Math.max(0, matchIndex - 100), Math.min(bodyText.length, matchIndex + 300)) : null,
    totalLinks: allLinks.length,
    productLinks: allLinks.filter(l => l.href.includes(".product.") || l.href.includes("/p/"))
  };
});
console.log(JSON.stringify(results, null, 2));

