const tabId = 480038583;
const details = await browserjs(tabId, () => {
  // Let's get the list of newest sets in order under Mega Evolution and Scarlet & Violet
  const headers = Array.from(document.querySelectorAll("h1, h2, h3, .series-name, .header"));
  const allSets = Array.from(document.querySelectorAll(".set, a.button, a[href*='-Set'], a[href*='-Expansion']")).map(a => {
    const img = a.querySelector("img");
    return {
      name: a.innerText.trim(),
      href: a.href,
      imgSrc: img?.src
    };
  }).filter(x => x.name.length > 0);

  return {
    headers: headers.map(h => h.innerText.trim()),
    sets: allSets.slice(0, 20)
  };
});
console.log(JSON.stringify(details, null, 2));

